import XCTest
@testable import NorseHorsePGPCore

/// Third-party provenance for the v6 (RFC 9580) extractors: the key material here
/// was generated by Sequoia PGP (via pysequoia, Profile.RFC9580), not by this
/// project's own generator or a hand-rolled encoder. Sequoia emits the encryption
/// subkey before the signing subkey and interleaves self-signature and user-ID
/// packets, so a green run proves the extractors select by key type (tag + algo)
/// rather than position, and interoperate with an independent OpenPGP stack.
final class V6SequoiaConformanceTests: XCTestCase {

    // Ed25519 signing SUBKEY fingerprint (SHA-256), the inline-signature issuer.
    static let aliceSignSubkeyFpr = "6D051D3F68A4D26FBA791896497631D05D8840AF5143C5FB76178B335802FE75"

    static let aliceSecB64 = ""
    static let alicePubB64 = ""
    static let bobSecB64 = ""
    static let bobPubB64 = ""

    private func d(_ b64: String) -> Data { Data(base64Encoded: b64)! }
    private func hex(_ b: [UInt8]) -> String { b.map { String(format: "%02X", $0) }.joined() }

    func testSequoiaV6KeysParse() throws {
        let aliceSign = try OpenPGPPacketParser.ed25519SigningInfo(fromV6SecretKey: d(Self.aliceSecB64), passphrase: nil)
        XCTAssertEqual(aliceSign.fingerprint.count, 32)
        XCTAssertEqual(hex(aliceSign.fingerprint), Self.aliceSignSubkeyFpr, "sequoia signing subkey fingerprint")

        let bobDec = try OpenPGPPacketParser.x25519DecryptionKey(fromV6SecretKey: d(Self.bobSecB64), passphrase: nil)
        let bobRcpt = try OpenPGPPacketParser.x25519Recipient(fromV6PublicKey: d(Self.bobPubB64))
        XCTAssertEqual(bobDec.privateKey.count, 32)
        XCTAssertEqual(bobRcpt.subkeyPublicKey.count, 32)
        XCTAssertEqual(bobRcpt.subkeyID, bobDec.subkeyID, "sequoia recipient/decryption key IDs match")
    }

    func testSequoiaV6RoundTrip() throws {
        let plaintext = Data("carrierpony <-> sequoia v6 interop".utf8)

        let aliceSign = try OpenPGPPacketParser.ed25519SigningInfo(fromV6SecretKey: d(Self.aliceSecB64), passphrase: nil)
        let bobRcpt = try OpenPGPPacketParser.x25519Recipient(fromV6PublicKey: d(Self.bobPubB64))
        let envelope = try OpenPGPPacketBuilder.buildEncryptedMessage(
            plaintext: plaintext, recipients: [bobRcpt], signingInfo: aliceSign, armor: false)

        let bobDec = try OpenPGPPacketParser.x25519DecryptionKey(fromV6SecretKey: d(Self.bobSecB64), passphrase: nil)
        let contents = try OpenPGPPacketParser.decryptMessageReturningInnerPackets(
            messageData: envelope, decryptionKeys: [bobDec])
        XCTAssertEqual(contents.literalData, plaintext, "sequoia-key round-trip plaintext")

        let claimed = OpenPGPPacketParser.claimedSignerFingerprint(contents: contents)
        XCTAssertEqual(claimed, Self.aliceSignSubkeyFpr, "sender from sequoia signing subkey")

        let aliceEd = try OpenPGPPacketParser.ed25519SigningSubkeyPublicKey(fromV6PublicKey: d(Self.alicePubB64))
        XCTAssertTrue(try OpenPGPPacketParser.verifyInlineSignature(
            contents: contents, signerEd25519PublicKey: aliceEd), "sequoia-key inline signature verifies")
    }

    func testSequoiaV6BinaryPayload() throws {
        var bytes = [UInt8](0...255); bytes.append(0x2A)
        let plaintext = Data(bytes)

        let aliceSign = try OpenPGPPacketParser.ed25519SigningInfo(fromV6SecretKey: d(Self.aliceSecB64), passphrase: nil)
        let bobRcpt = try OpenPGPPacketParser.x25519Recipient(fromV6PublicKey: d(Self.bobPubB64))
        let envelope = try OpenPGPPacketBuilder.buildEncryptedMessage(
            plaintext: plaintext, recipients: [bobRcpt], signingInfo: aliceSign, armor: false)

        let bobDec = try OpenPGPPacketParser.x25519DecryptionKey(fromV6SecretKey: d(Self.bobSecB64), passphrase: nil)
        let contents = try OpenPGPPacketParser.decryptMessageReturningInnerPackets(
            messageData: envelope, decryptionKeys: [bobDec])
        XCTAssertEqual(contents.literalData, plaintext)
    }
}
